local _, ns = ...
ns.chapters = {
  [529] = {
    start = { title = "In the Light", { "Come in, come in! No, stand there, in the light, where I can see you properly." }, { "You have the look of someone who can swing a weapon and has not yet been told what for. That is where I come in. The Dawn has one enemy, the dead, and no interest at all in which of the living you came from. Take our commission. What the Scourge carries on it is of great interest to me, and then we shall know what you are." }, { "One more thing. Everything in this world that is pushed too far becomes its own enemy. Courage. Faith. The Light itself. Remember that. I shall ask you about it later." } },
    friendly = { title = "Insignia", { "You have been about the Plaguelands long enough now that we may talk as colleagues." }, { "Do you know what they carry, the dead? Insignia. The Scourge is an army, and an army has ranks, even when its soldiers are dead. The common stones mark its rank and file. The rarer mark its elite. The rarest belong to its masters, the creatures that give the orders, and they are worth a great deal more than the rest. I keep the count. Some nights it is the only proof I have that we are winning." }, { "Every set brought to me earns a token. Somewhere in the Plaguelands, a thing that once took orders has stopped taking them. I find that very satisfying. I suspect that says something about me, and I have no intention of finding out what." } },
    honored = { title = "A Spine of Iron", { "I promised to ask you about extremes. Here is my question. What do you call a man who fights the Scourge, prays to the Light, and kills the innocent because he will not trouble to tell them from the guilty? The Scarlet Crusade calls him a crusader. I call him a blasphemer!" }, { "They hold part of Stratholme. Inside it, a man named Galford keeps their archive, years of what they are pleased to call intelligence." }, { "I want it burned. I want him dead. Tell me that is unreasonable. Go on.", before = 5251 }, { "You burned it for me, and that night I slept better than I have in years. Tell me that was unreasonable. Go on.", after = 5251 }, { "You see, we of the Dawn are tolerant. Tolerance is not softness. It needs a spine of iron, or the first fanatic to come along will bend it double. I have a spine of iron." } },
    revered = { title = "Those Who Come Back", { "You will have noticed that I am always here when you return. I send. That is what I do. I send people like you into Stratholme and the dead fields, and I wait at Light's Hope and count what comes back, the stones and the people. The stones always come back." }, { "So I keep two counts. The stones go in the ledger, where the quartermasters can see them. The other count I keep nowhere at all, and I could recite every line of it to you." }, { "You will also have noticed that I never call the Scourge's rank and file weak. I learned why from the ones who did not come back." }, { "Naxxramas is up there, Kel'Thuzad's citadel, and the Dawn will send people into it. Some of them will be people I sent somewhere else first." }, { "And you brought me a demon's head out of Stratholme, and I have not yet decided what it means. Those people in red believed they served the Light. They were serving a dreadlord. I called them blasphemers. I should like to know what to call them now.", after = 5262 } },
    aside = { title = "The aside", { "You are still coming back. I have stopped being surprised by it, which, I warn you, is the first step towards depending on it." } },
    exalted = { title = "Champion", { "Champion." }, { "Kneel. No, do not kneel. I am not a king, and you would only get up again with that look on your face." }, { "I have not called anyone that in years. I should like you to understand that I do not use the word loosely, because I do not use anything loosely, as you may have noticed." }, { "I told you once that everything pushed too far becomes its own enemy. I have thought about it a great deal since, which is your fault. I am a man who would burn a library for the Light and call the smoke a sermon. If anyone in this chapel is in danger of becoming what he hates, my friend, it is not you." }, { "That is why I need you. A champion is not someone who agrees with me. A champion is someone I trust to tell me when I have gone too far, and whom I will believe. I have not had one for a long time." }, { "The war is not over. One day the Dawn will go against the master of all this, wherever he sits, and on that day I should like you near me. Not in front. Near." } },
  },
  [576] = {
    start = { title = "The Door", { "I saw you coming up the road. You want the tunnel. Strangers always want the tunnel, because it is shorter than the mountains. It is not yours." }, { "We are the Timbermaw, the last tribe the corruption has not taken. You have met the others. Everyone has, and everyone shoots first now, without stopping to look. So do we." }, { "Grazle will tell you how to change our minds. Grazle tells everyone everything. Do what he asks, and then do it again." }, { "I will be here, at the door. I have one eye. For you, it is enough." } },
    friendly = { title = "The Count", { "From here on, it is counting." }, { "Feathers off the headdresses of the Deadwood, to Nafien at the gate or to Grazle, for those who bring them. They tell me the count whether I ask or not. I do not enjoy it. The Deadwood were our kin before the fel got into Felwood and into them, and a feather does not say which of them it was." }, { "The beads are worse. The Winterfall carried them against foul spirits. You can see how well that went. They wore their wards, the foulness walked in anyway, and now their beads go to Salfa in strangers' bags." }, { "Salfa thinks you are useful, and Salfa is seldom wrong. I still watch you." } },
    honored = { title = "What Few Have Asked", { "You have walked the hold so often now that the guards no longer reach for anything when you pass. So here is something, and you may do with it whatever your kind does with things it is told." }, { "The night elves took our help once, against the demons, and many of them took it holding their noses. Some of them have not stopped. Ask the Sentinels, on a day they feel honest." }, { "The Winterfall were our friends, and not long ago. Then their high chief began to want things nobody understood, and his tribe turned on everyone near it, us with the rest. Since then we keep to ourselves. We learned that much." }, { "Your people write their history down. We do not. And what we hold dearest, you have walked through a hundred times without seeing. Not yet." } },
    revered = { title = "Said Once", { "I will say this once, and you will not repeat it to Grazle." }, { "We cannot hold this place alone. Salfa tells strangers so, because Salfa is honest to a fault. I say it to you because you are not a stranger any more, which I did not expect to be saying this year. If the Winterfall and the Deadwood came at us from two sides at once, we would need every friend we have, and there are not many." }, { "Your kings have sent word to this hold before. The dwarf king under his mountain. The warchief of the orcs, in Durotar. They wanted to talk. There was no peace. I could give you the reasons, but you would not like them, and most of them would be about your people." }, { "You are Revered among us. Here the word means something plainer than it does among you. It means that if you fell at the door, someone would come out for you. It would be me. I would complain the whole way." } },
    aside = { title = "The aside", { "Still here. Still counting. Salfa says you are halfway to something. Salfa likes saying things like that. When you have arrived, you will hear it from me." } },
    exalted = { title = "Walk Slower", { "Walk slower through the hold from now on. You will, once you know why." }, { "You think this place is a road. A good road, out of the snow, with furbolgs in it who have learned not to shoot you. It was never a road. The hold was made for Ursoc and Ursol, the twin bears we honor, and every tunnel you have hurried through to save yourself a mountain is part of it. We let those we trust walk through a holy place. Most of them never knew what it was. Now you do." }, { "You will ask about the eye. Everyone who gets this far asks about the eye. No." }, { "I was the last in this hold to trust you, and I would like that remembered, because I was right to be slow. Trust that comes easily leaves the same way. Mine came the slow way, and it is not going anywhere." }, { "There is one more thing, and we do not give it to many. In a bad hour, far from here, one of our ancestors will come and stand with you, and mend you while it fights. Not for small hours. They are old, and they are ours, and they come as a favor to me.", after = 8481 } },
  },
  [59] = {
    start = { title = "Insects", { "An insect. At my table. Speaking to me." }, { "We have no business with insects, and I have no patience for them. You have nothing I want, you know nothing I need, and you are blocking my view of the door. The Brotherhood walked out on the emperor long ago. I still drink in his city. Neither is your business." }, { "The Brotherhood keeps a house at Thorium Point for strays, where they are kinder. Be a stray there first. If they ever learn your name, come back, and I will consider learning it too." }, { "Until then, away. Away." } },
    friendly = { title = "Terms", { "Thorium Point knows your name. So. Stand where I can see you, and hear the terms." }, { "We went down into the Fire Lord's halls once, for his cores and his leather and the blood of the mountain, which is his own tears. Many of us went down and did not come up again. Now you go. You are cheaper. Nothing personal. At TB Ltd., nothing ever is." }, { "Favor opens the Brotherhood's books, the plans and patterns nobody else in this world will sell you. It is the one coin I take that does not tarnish. Gold I can have from anyone." }, { "The offering is weighed. The offering is found sufficient. Do not let it go to your head." } },
    honored = { title = "The Small Knife", { "The Brotherhood receives you, and acknowledges your... oh, sit, if you like. Nobody sits with me. That is how you know it is an honor." }, { "You think we are Dark Irons who grew a conscience. Half of that is right. We were a guild before we were anything else, a craft guild in Ironforge, when there was one Ironforge and the clans had not yet gone to war over it. A frightened guild. We were sure our rivals knew secrets we did not. So we got hold of their best work and took it apart to see. That is how we found enchantment. Not by study. By theft, and patience, and a very small knife." }, { "When the war came and the clans chose sides, we chose. You know which. I will not apologize for it to a stranger, and I am still deciding what you are, so I will not apologize to you either." }, { "Our best secret, we stole first." } },
    revered = { title = "The Waste", { "The Brotherhood will hear your question. No. I will." }, { "You want to know why we left. Not the short version." }, { "When the Fire Lord woke, the mountain was his, and so were we. The emperor's people became his servants, and the Brotherhood became his smiths. We worked his forges. We made his weapons, the same blade over and over, for an army that did not care how well a thing was made. Understand me. It was not the cruelty. Dwarves can bear cruelty. It was the waste. The finest hands under the mountain, hammering out the same sword for creatures who could not tell it from a worse one." }, { "It was my apprentice who found the way out. Oilfist. Overseer Oilfist now, at Thorium Point, running the place like a garrison. He planned it under the overseers' noses, and we made what we needed to walk out of the Depths. Most who got free ran as far as their legs would carry them. We stopped across the Gorge. The materials are here. Craft does not run." }, { "And why am I here, at a table in the emperor's own city? The ale. Next question." } },
    aside = { title = "The aside", { "You again. Sit. No, not there. There. You have earned the better chair, which is the same chair, but I will know." } },
    exalted = { title = "Partners", { "No more ceremony. You and I are past weighing offerings. Listen, plainly, because this is the only way I talk to you now." }, { "The Brotherhood holds the secret of the Fire Lord's hammer. Sulfuras. The great maul he carries down there in the Core. We can teach a smith to forge the Sulfuron hammer, and with the Eye of Sulfuras set into it, a hero could carry the Hand of Ragnaros out into the world. Think about what that means. We spent an age making weapons for him. Now we sell the making of his own to anyone strong enough to kill him, at a fair price. I have never been so pleased with a piece of business in my life." }, { "I lose my head about it. Put a Sulfuron ingot in front of me and I will shout. I know. I do not care." }, { "Here is the other thing, since you are past the door. A guild like ours does not live on craft alone. When a rival grows too good, now and then, his forge has an accident. We are never anywhere near it. You will remember that we are never anywhere near it." }, { "You came to my table an insect. You leave it a partner. Read your contracts, all of them. Mine especially." } },
  },
  [609] = {
    start = { title = "The Other Enemy", { "Welcome to the Hold! Everybody here watches the bugs. They're big, there are a great many of them, and they sit in their hives and behind that wall as if they're waiting for something, so I don't blame anyone for watching." }, { "But turn around. The cultists out in the desert aren't waiting. They're building, and calling, and passing each other notes in scribble. My big brother Huum and I stay on them, because somebody has to and nobody else will." }, { "Bugs, we've got plenty. A real fight, I've got better." } },
    friendly = { title = "Scribbles", { "The cult's papers are what I want most. Little scraps covered in scribble. That's how their camps talk to each other!" }, { "I can't read them, and I don't need to. Every stack taken off a dead cultist is a message that never arrives, an order nobody gets, a camp waiting for word and hearing nothing. That's a fight too. A quiet one, but a fight." }, { "Huum would want to read them. Huum listens to things, the land, the spirits, papers too, I expect. Me, I stash them. Someday someone clever will want them, and until then every scrap in my stash is one the cult never gets to read." } },
    honored = { title = "My Big Brother", { "Here. You've earned a story, and I've got one, and it's mostly about my brother." }, { "My people, I always say, do things slowly, listening first. Huum is one of my people all the way through. Huum listens first. He says the spirits here are calling him, and the sand is grieving over something it needs someone to hear." }, { "I don't hear it. I've tried, hard, the way I try everything. I stand where he stands and all I get is sand in my ears. But I believe him. Because he's my brother. Because I've never once managed to prove him wrong. And because when he goes quiet in the evening, he stays quiet too long." }, { "So I fight, and he listens, and between the two of us the Hold has what it needs." } },
    revered = { title = "What They Call Up", { "What keeps me up at night is a short list. It keeps me up, so it can keep you up too." }, { "The cult isn't only praying out there. They're calling things up out of the summoning stones: templars, then dukes, then lords, each one bigger than the last and each one a bigger headache for me. And each one hands down orders. We know they can be smashed. What we don't know is who they answer to. Maybe the cult worships them. Maybe they're only messengers, and whatever sends the messages hasn't shown itself yet." }, { "So, the list. The bugs in their hives and behind the wall. The cult in the desert. Whatever the cult calls up. Whatever has Huum so quiet in the evenings. That's a lot of enemies for one stretch of sand." }, { "Everyone tells me to wait and watch. I've been waiting and watching a long time. It hasn't grown on me." } },
    aside = { title = "My Post", { "Same post, same sand. Go wrestle the big ones for me, and come back and tell me how hard they hit!" } },
    exalted = { title = "The Biggest Chest", { "You know what I'd give you, if I could give you anything? My post. Just for a day." }, { "That chest was no use as a thank you. I heard you laugh when you opened it, and I know it wasn't the chest you were laughing at.", after = 8352 }, { "I'd walk out of the Hold with you, past the camps and the stones and out into the desert, and we'd find the biggest thing the cult can call and find out together how hard it hits!" }, { "I can't. Someone has to stand here, and it's me. So instead I'll tell you the thing I tell nobody. When Huum goes quiet in the evening, I watch him. Him, not whatever he's listening to. He's the one I'm guarding. The Hold, the wall, the papers, all of it, I'd trade for him without a second thought, and that's a terrible thing to say when you're standing guard." }, { "Huum would tell me the land needs guarding more than he does. Huum would be right. I'd still pick him." }, { "You're the only one I've said it to." } },
  },
  [270] = {
    start = { title = "Not Yet", { "Welcome. They call me Rin'wosho, and I trade out of Zuldazar, a long way from home and further still from my best customers." }, { "You will want to see what I carry. Everyone does. Goods of the South Seas, patterns for your tailors and your leatherworkers, fruit you have never tasted. And I would love to sell them to you. But I barter only with friends of my tribe, and you are not one yet." }, { "The Zandalar are at war with a god who should have stayed gone. Help them in that, then come back, and we will talk prices." } },
    friendly = { title = "Honor, in Coin", { "Now we can do business, my friend." }, { "Among the Zandalar it goes like this. What you carry out of Zul'Gurub for the tribe, the tribe repays in honor, in tokens to keep and to spend with me. I like a people whose gratitude fits in a purse. Spend them or keep them, as you please. I have known people keep one for years, for no reason they could name." }, { "The coins the trolls of that city carry are another matter. Each of those peoples has its own, every one of them thick with mojo, and Vinchaxa takes them for the tribe's use. I would not haggle over those. Some things are worth more than they buy." } },
    honored = { title = "The Mango", { "You have never eaten an essence mango. Nobody who has tasted one asks what it is." }, { "They grow wherever the South Seas have a beach to grow on. One of them and you are rested, body and thought together, as if you had slept a night on the sand at home. I keep a supply here on the isle for those the tribe has come to respect. I could sell them here for a small fortune. I do not. Some fruit is only for friends." }, { "I do not miss Zuldazar for its king or its priests. I miss it for the fruit, and the sea, and my own language spoken by people who are not afraid. Here everyone is afraid. You can hear it in how quietly the isle talks once the sun is down. Here even the fruit tastes a long way from home." } },
    revered = { title = "What the Priests Took", { "With your standing come my most potent brews, the ones Zanza has blessed. Take one at a time, my friend. A blessing is not a thing you stack." }, { "Hear now why the tribe hands its blessings to outsiders at all. In Zul'Gurub the high priests are the Soulflayer's thralls, and through them he drinks our gods. Not their blood. Their strength. Every day he holds that city, the oldest powers my people know grow a little weaker, and he a little stronger, and no one can tell me where the bottom of that lies." }, { "I sleep badly on this isle. A merchant knows what leaves his shelves, and I can no longer reckon what leaves the gods. Some nights I walk the beach and talk to the sea in my own language, so that something on this isle still hears it." }, { "So when I hand you a blessed brew, that is no generosity. That is stock moved before the warehouse burns." } },
    aside = { title = "Regular Customer", { "A mango? Careful. A merchant who serves the same customer twice grows fond of them, and fondness is very bad for prices." } },
    exalted = { title = "From Home", { "These I sell to no one else. Signets, carried across the water from the South Seas, for the shoulders of those the tribe counts as its own. Might, mojo or serenity: I have fitted a great many shoulders in my life, and few of them carried anything worth the weight." }, { "Under every trade we have made lies one plain thing. The coins go into the tribe's defense against the god in that city, and the bijous are broken on Zanza's altar, every scrap of mojo turned against him. For a long time I told myself I was only selling. I stopped believing it some while ago. I think it was about when I began keeping the best mangoes back for you." }, { "I will go home one day, when the Soulflayer is ash and our gods are whole again. The sea will still be there. It is the one thing I have never had to bargain for. The first evening, I will eat a mango on the sand and think of this ugly little island, and I suspect I will miss it. When I go, I will tell them about you, and about your bargains." } },
  },
  [910] = {
    start = { title = "Beneath Notice", { "You need not lower your voice. Little that mortals say carries far among my kind. The bronze flight has not favored one of you in a very long while, and you begin with us where every mortal begins, which is nowhere at all." }, { "Do not take it hard. It is not hatred. We are slow to attend to anything that will not last." }, { "There, past the walls of the Hold, the hive is moving. The ground around it trembles, and the old enemy readies its war again. That is the thing worth minding. It is why I am here." } },
    friendly = { title = "Grains", { "So. You have begun to matter, a little. I felt it as one feels a single grain slip in an hourglass: hardly at all, and then there is no ignoring it." }, { "What the flight wants of mortals is simple and very hard. Every servant of the insects' masters that falls is a grain moved from their side of the glass to ours. I have tended that glass a long time. It is good to see another hand on it." }, { "A word about the bronze flight, which you have not asked for: we do not hurry. That is not the same as not caring. Remember it, the day we seem slow to you." } },
    honored = { title = "The Breath", { "I will give you an old story, if you will take it. I will tell it without ornament." }, { "I was dying once. I had nothing left to give, my wounds were open, and I was no longer afraid, which is how I knew how near the end had come. Then the master of my flight came to me." }, { "I do not remember the breath. I remember that afterwards I was no longer dying, and that I was told to remain, for as long as remaining was needed. So I became a Watcher. I have never found a better word for it than the one I was given." }, { "It was kindly done, and it has cost me ever since. Both of those are true, and I have stopped trying to make one of them smaller than the other." } },
    revered = { title = "The Oath", { "Long ago I swore an oath, and the time to keep it has come at last. What it was is mine. What keeping it feels like, I can give you." }, { "It feels like a door you have watched for so long that you forgot it could open. The hive stirs, the sands shift, the qiraji make ready, and all at once the waiting is over, and I find I did not want it to be. An oath kept is an oath you no longer carry. I have carried this one so long that I do not know my own weight without it." }, { "A Watcher fears one thing, and it is not the enemy. The enemy is honest. What a Watcher fears is the thought that the one you wait for will not come back, and that you will go on waiting anyway, out of habit, long after it means anything." }, { "I have had that thought every day for longer than your kind has had names." } },
    aside = { title = "The Hourglass", { "Halfway by your reckoning. By mine, a moment. Neither of us is wrong. Go on. The glass does not mind." } },
    exalted = { title = "Favor", { "No mortal has held the bronze flight's favor in a thousand years. I used to wonder whether one ever would, the way one wonders about rain in this desert: idly, out of habit, without hope." }, { "You hold it now. It means I will stop speaking to you as I speak to a stranger. That is all it means, and I find it is a great deal. For a very long time everyone I spoke to was a stranger, even those beside me, because some part of me was always turned toward the wall." }, { "You went to the Caverns of Time for me and found the master returned. My watch is over. I do not yet know what a Watcher does when the watching ends. Stay a while, and help me find out.", after = 8286 }, { "I have waited a long time for something to arrive. I did not expect it to be you. Waiting with someone beside me is a different thing, and I had forgotten how different. If you come back, however late, I will know you. I am glad to have been wrong about mortals. Some of them, at least. One." } },
  },
  [749] = {
    start = { title = "A Bargain", { "You were not born in water, and what we fight over will always be closed to you. Nothing here will be made clearer by pretending." }, { "A bargain needs no understanding. The Waterlords fight the lords of air, of earth and of fire, and it is fire we cannot forgive. You are small and short-lived, and you walk on land that burns. You have reasons of your own to want the fire put out. Your reasons and ours may run the same way for a while. I mean to use that." }, { "Prove useful, and the deep will remember you. It forgets almost everything." } },
    friendly = { title = "Purity", { "You have been useful. That is rarer than you would think, among your kind." }, { "Understand what we fight for. You are beside us now. What makes us strong is that we are pure. Water that takes in whatever it touches is no longer water, only a sickness that flows. When the plague of Lordaeron got into the elementals we sent there, what offended me was what they had become." }, { "Of one thing I know nothing. Our enemies of air and earth guard objects of power in the south, away from mortals, and I cannot tell you why. I know only that whatever they keep, I would rather they did not." } },
    honored = { title = "The Debate", { "They spoke of you in our chambers, and at length. That is not our way. You were the subject, not the judge, and it is right that you hear how it went." }, { "Some among us thought you a poor thing to spend on our war, a creature we would pour strength into only for it to crack. They were not wrong, and they are not wrong now. You are small. You do break. You came back anyway, against our enemies, again and again, and each return made their view a little harder to hold." }, { "None of us thought it possible. The Waterlords respect you now. It troubles the order of things in a way I have no word for, because a small thing should not weigh this much, and you do. The doubters have gone quiet, the way a current goes still before it turns." } },
    revered = { title = "The Loss Judged Worth It", { "The water has no mercy and no malice. I will speak the way it does." }, { "It costs us to lose a hand that has proved itself, and you have. To send one of you against the Firelord's own captains is the hardest thing we ask, and we ask it only when the gain is judged worth the loss. That judgment is the highest compliment the Waterlords know how to pay. I would not blame you for not hearing it as one. We have spent agents before, and the water closed over them. It would not close so quickly over you." }, { "Beneath the mountain the floor is cut with runes of fire. Each one is a door to its realm, and each one feeds it. When a rune goes out, one door shuts, the fire draws a little less from home, and it is a little more alone in the world. That is all we want of it: that it be alone, and then that it be gone." } },
    aside = { title = "The Tide", { "The tide has turned a little in our favor, and some of that is your doing. A little. It is a large tide, and you are a small creature, and still it moved." } },
    exalted = { title = "Legend", { "Gratitude is a mortal habit. Among us, nothing is owed for work well done. The current does its work and no one praises it for that. The sea does not thank the river for arriving." }, { "You have fought for us with a steadiness I did not think a creature of your size could keep, and I want to give you something. I tried to think what one of you would want, and could not. So I give you what we would want, if we wanted anything. It is the nearest thing to thanks we have, and I am told that among your kind it is customary to say so aloud, so I have. Take it, then: a source of our quintessence that will not run dry. I do not set a term." }, { "You brought me the hands of the Firelord's captains. Word of it ran down through our deep halls like a current. I allowed once that you might end as a legend here. I was cautious. You are one already.", after = 6824 }, { "You are small, and you will not last. I still think both of those things. The deep forgets almost everything. It has decided to keep you." } },
  },
  [2778] = {
    start = { title = "The Empty Sky", { "Look up. Higher. You see the sprites drifting about the island and you think the winds still keep us company. They only wear the winds' shape. The spirits who carried my people into Skywall, who spoke with us and held this island up, have been silent a long time." }, { "The Windshapers have sworn to find where they went and fetch them back, whatever it costs and however far down the road goes. Walk it with us, or walk it somewhere my word does not follow." } },
    friendly = { title = "What We Owe", { "You stayed. Then you are owed the truth of what it means to stand with the Windshapers." }, { "The spirits gave us their gifts, instruments and constructs both, and we tend them still. We read the wind, because the wind is the last of them that still moves. And we watch the land. It is opening, the ley lines rising through it, and our word for the wounds is scars. The magisters of the High Order would sooner study a scar than ask what made it." }, { "The Al'Aketh we do not watch. We answer them, every time. That is not a thing I soften for anyone." }, { "What you do for us is not a favor. It is part of a debt, and the debt is ours." }, { "The shrine fell and its priestess ran. Whatever shielded this island from the Windlord is gone now. I read the sky every night. So far it has only looked back.", after = 93836 } },
  },
  [2779] = {
    start = { title = "What We Forgot", { "You find us searching. An order of scholars that has lost most of what it knew does little else." }, { "We are alone now. The winds that carried my people into Skywall are gone, and I say so plainly because most of the island still cannot. We were Highborne scholars once, and somewhere in the long years since, we forgot how to do anything the winds did not do for us. The High Order intends to remember." }, { "There is work here for anyone willing to look." } },
    friendly = { title = "Below Us", { "Some come to the High Order born to it, some by choice, and I have stopped asking which. What matters is what you will do with it." }, { "Here is what we do. We look for what our ancestors knew before the winds made knowing unnecessary: the arcane of Eldre'Thalas, a strength that does not depend on anyone's kindness. An archmage of the Kirin Tor in Dalaran answers my letters, which is more than the winds have done in a long time. Azeroth went on learning while we drifted. It will teach us, if we are humble enough to ask." }, { "The Windshapers think us reckless. You will hear them say so. Hear them out, then come back here and do the work anyway." }, { "I sent Belathaan to the shrine to talk. I was certain talk was possible. I have been certain of very little since, and I find I work better that way.", after = 92834 } },
  },
}
-- (the places Classic Era's client names otherwise, swapped in there)
